"""Summarize mailbox letters without changing the input tree."""
import argparse
from datetime import datetime, timedelta
import json
from pathlib import Path
import re
import sys


NAME = re.compile(r"^[0-9]{8}T[0-9]{4}[-_]")
RESOLVING = {"DONE", "BLOCKED", "NEEDS-USER", "FAILED"}
REQUIRED = ("id", "from", "to", "status", "at")


def read_letter(path, now):
    try:
        # Split only on file newlines, not Unicode characters inside field values.
        lines = path.read_text(encoding="utf-8").split("\n")
    except (OSError, UnicodeError):
        return None, "no_frontmatter"
    if not lines or lines[0] != "---":
        return None, "no_frontmatter"
    try:
        end = lines.index("---", 1)
    except ValueError:
        return None, "no_frontmatter"
    fields = {}
    for line in lines[1:end]:
        if ": " in line:
            key, value = line.split(": ", 1)
            fields[key] = value
    if any(not fields.get(key) for key in REQUIRED):
        return None, "no_field"
    try:
        at = datetime.fromisoformat(fields["at"])
    except (TypeError, ValueError):
        return None, "no_field"
    if at.tzinfo is None:
        at = at.replace(tzinfo=now.tzinfo)
    if not NAME.match(path.name):
        return None, "bad_name"
    try:
        datetime.strptime(path.name[:13], "%Y%m%dT%H%M")
    except ValueError:
        return None, "bad_name"
    return (fields, at), None


def summarize(root, now):
    boxes = {}
    candidates = []
    for mailbox in sorted(root.iterdir(), key=lambda path: path.name):
        if mailbox.name.startswith(".") or not mailbox.is_dir():
            continue
        inbox = mailbox / "inbox"
        if not inbox.is_dir():
            continue
        boxes[mailbox.name] = {"inbox": {}, "done": 0}
        for directory, where in ((inbox, "inbox"), (inbox / "done", "done")):
            if not directory.is_dir():
                continue
            for path in directory.iterdir():
                if (path.name.startswith(".") or path.suffix != ".md"
                        or path.is_symlink() or not path.is_file()):
                    continue
                relative = path.relative_to(root).as_posix()
                candidates.append((relative, path, mailbox.name, where))

    bad = []
    valid = []
    seen_ids = set()
    for relative, path, box, where in sorted(candidates):
        letter, why = read_letter(path, now)
        if why is None and letter[0]["id"] in seen_ids:
            why = "dup_id"
        if why is not None:
            bad.append({"file": relative, "why": why})
            continue
        fields, at = letter
        seen_ids.add(fields["id"])
        valid.append((fields, at, box, where))
        if where == "done":
            boxes[box]["done"] += 1
        else:
            counts = boxes[box]["inbox"]
            counts[fields["status"]] = counts.get(fields["status"], 0) + 1

    resolved = {fields.get("re") for fields, _, _, _ in valid
                if fields["status"] in RESOLVING}
    opened = []
    for fields, at, _, where in valid:
        if fields["status"] == "REQUEST" and fields["id"] not in resolved:
            opened.append({"id": fields["id"], "from": fields["from"],
                           "to": fields["to"], "where": where,
                           "age_min": (now - at) // timedelta(minutes=1)})
    opened.sort(key=lambda item: (item["to"], item["id"]))
    bad.sort(key=lambda item: (item["file"], item["why"]))
    return {"v": 1, "open": opened, "boxes": boxes, "bad": bad}


def main(argv=None):
    parser = argparse.ArgumentParser(description="Read-only mailbox summary")
    parser.add_argument("folder", type=Path)
    parser.add_argument("--now", required=True)
    args = parser.parse_args(argv)
    try:
        now = datetime.fromisoformat(args.now)
    except ValueError:
        parser.error("--now must be an ISO datetime with a timezone")
    if now.tzinfo is None:
        parser.error("--now must have a timezone")
    if not args.folder.is_dir():
        parser.error("folder must be an existing directory")
    print(json.dumps(summarize(args.folder, now), ensure_ascii=False,
                     separators=(",", ":")))
    return 0


if __name__ == "__main__":
    sys.exit(main())
